from solution import fibfib
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(n: int) -> int:
    # Obviously-correct iterative model directly from spec definition.
    assert n >= 0
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c


def test_spec_example_fibfib_1():
    assert fibfib(1) == 0


def test_spec_example_fibfib_5():
    assert fibfib(5) == 4


def test_spec_example_fibfib_8():
    assert fibfib(8) == 24


def test_spec_base_cases():
    assert fibfib(0) == 0
    assert fibfib(1) == 0
    assert fibfib(2) == 1


def test_spec_table_first_eleven():
    expected = [0, 0, 1, 1, 2, 4, 7, 13, 24, 44, 81]
    for n, v in enumerate(expected):
        assert fibfib(n) == v, f"n={n}"


def test_recurrence_relation():
    # Spec: fibfib(n) == fibfib(n-1)+fibfib(n-2)+fibfib(n-3)
    for n in range(3, 30):
        assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3), f"n={n}"


@given(st.integers(min_value=0, max_value=30))
def test_matches_reference_model(n):
    assert fibfib(n) == reference(n)


@given(st.integers(min_value=3, max_value=30))
def test_recurrence_property_hypothesis(n):
    assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


@given(st.integers(min_value=0, max_value=30))
def test_non_negative(n):
    assert fibfib(n) >= 0


@given(st.integers(min_value=1, max_value=30))
def test_monotone_nondecreasing_from_1(n):
    # All values >= 0 implies sums dominate: fibfib(n+1) >= fibfib(n) for n >= 1.
    assert fibfib(n + 1) >= fibfib(n)


@given(st.integers(min_value=0, max_value=30))
def test_strictly_increasing_after_3(n):
    # For n >= 3 values are strictly increasing (verifiable from table + recurrence).
    m = n + 3
    assert fibfib(m + 1) > fibfib(m)


def test_efficient_large_n_correctness():
    # "efficiently compute": must handle moderately large n quickly and exactly.
    assert fibfib(100) == reference(100)
    assert fibfib(500) == reference(500)
    assert fibfib(1000) == reference(1000)


def test_returns_int():
    for n in [0, 1, 2, 5, 8, 20]:
        assert isinstance(fibfib(n), int)
